html:
{#- Sidra Sale Contract print (SAL-06, SAL-12, SAL-13, SAL-19, SAL-20, INS-21).
    English headings; the Somali headings and contract body wording are pending from Sidra (issue #8).
    Shows only this contract's frozen clauses, each in Somali and English. -#}
<style>
	.sidra-contract { font-size: 11pt; }
	.sidra-contract h2 { margin-bottom: 4px; }
	.sidra-contract h3 { margin: 18px 0 6px; border-bottom: 1px solid #999; }
	.sidra-contract table { width: 100%; border-collapse: collapse; margin-bottom: 8px; }
	.sidra-contract th, .sidra-contract td { border: 1px solid #bbb; padding: 3px 6px; vertical-align: top; text-align: left; }
	.sidra-contract .draft { color: #a00; font-weight: bold; }
	.sidra-contract .clause-so { margin: 4px 0; }
	.sidra-contract .clause-en { margin: 4px 0 10px; color: #333; }
	.sidra-contract .sign { height: 48px; }
</style>
<div class="sidra-contract">
	<div class="sidra-letterhead" style="text-align:center;margin-bottom:8px"><img src="{{ frappe.utils.get_url() }}/assets/sidra_realestate/images/sidra-logo.png" alt="Sidra Homes" style="height:60px"></div>
	<h2>Sale Contract {{ doc.name | e }}</h2>
	{% if doc.docstatus == 0 %}<p class="draft">Draft for signing — not yet signed or notarised</p>{% endif %}

	<table>
		<tr><th>Contract date</th><td>{{ doc.get_formatted("signed_on") }}</td><th>Contract type</th><td>{{ doc.contract_type | e }}</td></tr>
		<tr><th>Seller</th><td>{{ doc.company | e }}</td><th>Buyer</th><td>{{ frappe.db.get_value("Customer", doc.customer, "customer_name") | e }}</td></tr>
		{% if doc.buyer_agent_name %}
		<tr><th>Buyer agent (wakiil)</th><td>{{ doc.buyer_agent_name | e }}</td><th>Agent phone</th><td>{{ (doc.buyer_agent_phone or "") | e }}</td></tr>
		{% endif %}
	</table>

	<h3>Units</h3>
	<table>
		<tr><th>Unit</th><th>Location</th><th>Size</th><th>Boundaries</th><th>Price</th></tr>
		{% for row in doc.units %}
		{%- set u = frappe.db.get_value("Sidra Unit", row.unit, ["scheme", "dimensions", "plot_fraction", "district", "neighbourhood", "land_parcel", "boundary_east", "boundary_north", "boundary_south", "boundary_west"], as_dict=True) or {} -%}
		<tr>
			<td>{{ row.unit | e }}<br>{{ (u.scheme or "") | e }}</td>
			<td>{{ (u.district or "") | e }}{% if u.neighbourhood %}, {{ u.neighbourhood | e }}{% endif %}{% if u.land_parcel %}<br>{{ u.land_parcel | e }}{% endif %}</td>
			<td>{{ (u.dimensions or "") | e }}{% if u.plot_fraction %} ({{ u.plot_fraction | e }}){% endif %}</td>
			<td>East: {{ (u.boundary_east or "") | e }}<br>North: {{ (u.boundary_north or "") | e }}<br>South: {{ (u.boundary_south or "") | e }}<br>West: {{ (u.boundary_west or "") | e }}</td>
			<td>{{ row.get_formatted("allocated_price", doc) }}</td>
		</tr>
		{% endfor %}
	</table>

	{% if doc.contract_type == "Installment" and doc.source == "External (registered)" %}
	<p><strong>Registered copy of an external contract — the attached original governs.</strong> External reference: {{ (doc.external_reference or "") | e }}</p>
	{% endif %}
	<h3>Price and payment</h3>
	<table>
		<tr><th>Agreed price</th><td>{{ doc.get_formatted("agreed_price") }}</td></tr>
		{% if doc.contract_type == "Installment" %}
		<tr><th>Down payment</th><td>{{ doc.get_formatted("down_payment") }}</td></tr>
		<tr><th>Balance in installments</th><td>{{ doc.get_formatted("balance") }}</td></tr>
		<tr><th>Installments</th><td>{{ doc.installments }}, due on day {{ doc.due_day }} of each month{% if doc.grace_months %}, after {{ doc.grace_months }} month(s) grace{% endif %}</td></tr>
		{% endif %}
	</table>
	{% if doc.schedule %}
	<table>
		<tr><th>No.</th><th>Type</th><th>Due date</th><th>Amount</th></tr>
		{% for line in doc.schedule %}<tr><td>{{ line.seq }}</td><td>{{ (line.row_type or "Installment") | e }}</td><td>{{ line.get_formatted("due_date", doc) }}</td><td>{{ line.get_formatted("amount", doc) }}</td></tr>{% endfor %}
	</table>
	{% endif %}

	{% if doc.clauses %}
	<h3>Clauses</h3>
	{% for c in doc.clauses %}
	<div class="clause">
		<strong>{{ loop.index }}. {{ c.title | e }}</strong>
		<div class="clause-so" lang="so">{{ (c.text_so or "") | e | replace("\n", "<br>") }}</div>
		<div class="clause-en" lang="en">{{ (c.text_en or "") | e | replace("\n", "<br>") }}</div>
	</div>
	{% endfor %}
	{% endif %}

	<h3>Parties and signatures</h3>
	<table>
		<tr><th>Role</th><th>Name</th><th>Phone</th><th>ID</th><th>Pledged property</th><th>Signature</th></tr>
		{% for p in doc.parties %}
		<tr><td>{{ p.role | e }}</td><td>{{ p.full_name | e }}</td><td>{{ (p.phone or "") | e }}</td><td>{{ (p.id_number or "") | e }}</td><td>{{ (p.pledged_property or "") | e }}</td><td class="sign"></td></tr>
		{% endfor %}
		<tr><td>Buyer</td><td>{{ frappe.db.get_value("Customer", doc.customer, "customer_name") | e }}</td><td></td><td></td><td></td><td class="sign"></td></tr>
	</table>

	<h3>Notary</h3>
	<table>
		<tr><th>Notary</th><td>{{ (doc.notary_name or "") | e }}</td><th>Reference</th><td>{{ (doc.notary_reference or "") | e }}</td></tr>
	</table>
</div>
